functions.assert_arm_together():
CREATE OR REPLACE FUNCTION public.assert_arm_together()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if NEW.state = 'armed' then
    if not exists (
      select 1 from open_loop l, jsonb_array_elements(l.contingencies) c
      where l.id = NEW.loop_id and c->>'branch_id' = NEW.branch_id
    ) then
      raise exception 'arm-together invariant (SPEC §3.1): timer.branch_id=% has no matching contingency on loop %',
        NEW.branch_id, NEW.loop_id;
    end if;
  end if;
  return NEW;
end;
$function$

functions.enforce_ctrl_event_write():
CREATE OR REPLACE FUNCTION public.enforce_ctrl_event_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if current_user = 'rocoto_ctrl' and NEW.type not like 'override.%' then
    raise exception 'tier-P (rocoto_ctrl) may only append override.* events (SPEC §15.7), got type=%', NEW.type;
  end if;
  return NEW;
end;
$function$

functions.rocoto_is_test_immutable():
CREATE OR REPLACE FUNCTION public.rocoto_is_test_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.is_test is distinct from old.is_test then
    raise exception 'is_test is immutable (table %)', tg_table_name;
  end if;
  return new;
end;
$function$
